/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pedidos` (
  `id_pedido` int NOT NULL AUTO_INCREMENT,
  `tipo` enum('Mantenimiento','Reparación','Soporte','Pedido Insumo','Tarea Interna') COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `solicitante_nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `solicitante_apellido` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `solicitante_telefono` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `solicitante_email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prioridad` enum('Baja','Media','Alta') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Media',
  `estado` enum('Pendiente','En Proceso','Preparado','Completado','Rechazado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pendiente',
  `id_usuario_solicitante` int NOT NULL COMMENT 'Usuario del sistema que carga el pedido',
  `id_sede` int NOT NULL,
  `id_area` int DEFAULT NULL,
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_preparacion` datetime DEFAULT NULL,
  `fecha_actualizacion` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `asignado_a` int DEFAULT NULL,
  `id_insumo_relacionado` int DEFAULT NULL,
  `id_remito_relacionado` int DEFAULT NULL,
  `insumo_relacionado` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pdf_nota` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remito_firmado` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_remito` int DEFAULT NULL,
  `metodo_entrega` enum('No aplica','Envío','Retiro') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'No aplica',
  `estado_entrega` enum('Pendiente','Preparado','Enviado','Entregado','De Baja') COLLATE utf8mb4_unicode_ci DEFAULT 'Pendiente',
  `fecha_entrega` datetime DEFAULT NULL,
  `fecha_estimada_entrega` date DEFAULT NULL,
  `receptor_nombre` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notas_entrega` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id_pedido`),
  KEY `idx_pedidos_usuario` (`id_usuario_solicitante`),
  KEY `idx_pedidos_sede` (`id_sede`),
  KEY `idx_pedidos_estado` (`estado`),
  KEY `idx_pedidos_asignado` (`asignado_a`),
  KEY `idx_pedidos_insumo` (`id_insumo_relacionado`),
  KEY `fk_pedidos_area` (`id_area`),
  KEY `fk_pedidos_remito_relacionado` (`id_remito_relacionado`),
  CONSTRAINT `fk_pedidos_area` FOREIGN KEY (`id_area`) REFERENCES `areas` (`id_area`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pedidos_asignado` FOREIGN KEY (`asignado_a`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pedidos_insumo` FOREIGN KEY (`id_insumo_relacionado`) REFERENCES `insumos` (`id_insumo`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pedidos_remito_relacionado` FOREIGN KEY (`id_remito_relacionado`) REFERENCES `remitos` (`id_remito`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pedidos_sede` FOREIGN KEY (`id_sede`) REFERENCES `sedes` (`id_sede`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pedidos_usuario` FOREIGN KEY (`id_usuario_solicitante`) REFERENCES `usuarios` (`id_usuario`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

