 09:46:17','2026-04-24 09:46:17','2026-05-05 09:38:51',12,314,NULL,'Varios - Cargador Notebook Silverstone','pedido_1777034777_69eb6619479a6.pdf','remito_entregado_1777545949_69f332dd0e248.pdf',NULL,'No aplica','Entregado','2026-04-30 07:45:49',NULL,'Nayibe Favreau',''),(7,'Pedido Insumo','','Lujan','Teruel',NULL,NULL,'Media','Completado',11,1,15,'2026-04-28 07:49:53','2026-04-28 07:49:53','2026-05-05 09:38:51',NULL,NULL,NULL,'WebCam 2k PJT-DCM173 USB','nota_sol_1777373393_69f090d138657.pdf','remito_entregado_1777374871_69f0969720ff6.pdf',250,'Retiro','Entregado','2026-04-28 08:14:31','2026-05-01','Pinchulef Vanesa',''),(8,'Pedido Insumo','','Nayibe','Favreau',NULL,NULL,'Media','Completado',14,16,2,'2026-04-29 10:18:29','2026-04-29 10:18:29','2026-05-21 09:06:57',NULL,NULL,NULL,'WebCam 2k PJT-DCM173 USB | Adaptador Auriculares Noganet Jack 3.5 | Auricular Genius C/Micro HS-200C | Parlante Genius SP-Q160 USB-Plug','nota_sol_1777468709_69f2052544c72.pdf','remito_entregado_1779365217_6a0ef56161bf6.pdf',268,'Envío','Entregado','2026-05-21 09:06:57','2026-05-04','Nayibe Favreau',''),(9,'Reparación','Ingresa Notebook para reparación. El equipo tenía instalado Sist Op. Wind 10 sin espacio en disco. Se hizo backup de toda información, se formateo y se instaló nuevo sistema operativo (Ubuntu 22) quedando con más espacio en disco y todas sus aplicaciones actualizadas. \r\nSe hicieron pruebas rigurosas para verificar su óptimo funcionamiento.','Clara','Houriet',NULL,NULL,'Media','Completado',12,21,11,'2026-04-30 09:52:28','2026-04-30 09:52:28','2026-05-21 09:53:09',12,330,NULL,'Notebook (S/N: 425801080)',NULL,'remito_entregado_1779367989_6a0f0035b97ad.pdf',NULL,'Envío','Entregado','2026-05-21 09:53:09','2026-04-30','Clara Houriet',''),(10,'Reparación','Ingresa notebook con pantalla negra.\r\nPresentaba problema de initranfs. Se corrigió con el comando correspondiente.','Clara','Houriet',NULL,NULL,'Media','Completado',12,21,11,'2026-04-30 09:58:48','2026-04-30 09:58:48','2026-0