DROP TABLE IF EXISTS `pedidos_informes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pedidos_informes` (
  `id_informe` int NOT NULL AUTO_INCREMENT,
  `id_pedido` int NOT NULL,
  `numero_informe` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `diagnostico` text COLLATE utf8mb4_unicode_ci,
  `trabajo_realizado` text COLLATE utf8mb4_unicode_ci,
  `resultado` enum('Solucionado','Sin Solución','Requiere Repuestos') COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_informe` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_informe`),
  KEY `idx_informes_pedido` (`id_pedido`),
  CONSTRAINT `fk_informes_pedido` FOREIGN KEY (`id_pedido`) REFERENCES `pedidos` (`id_pedido`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pedidos_informes`
--

LOCK TABLES `pedidos_informes` WRITE;
/*!40000 ALTER TABLE `pedidos_informes` DISABLE KEYS */;
INSERT INTO `pedidos_informes` VALUES (1,1,'0001_2026','No andaba el wifi.','Se realizaron pruebas y resulto que la placa de wifi estaba quemada, y no se puede reemplazar. Se envía con adaptador red para que la usen en un puerto que tiene disponible.','Solucionado','2026-04-08 06:24:11'),(2,5,'0002_2026','Error pantalla azúl windows','Se formateo el equipo y se instaló nuevo sistema operativo (Ubuntu 22) y se agregó tarjet SD de 64GB','Solucionado','2026-04-24 09:16:00'),(3,6,'0003_2026','El transformador no cargaba.','* Se chequeo completamente y verificamos que el cable presentaba cortes en varios sectores.\r\n* Se testeó con multímetro y notamos que el cargador no funcionaba.\r\nEl mismo no se remplazará por no contar con repuesto en stock.','Requiere Repuestos','2026-04-24 09:48:20'),(4,10,'0004_2026','Enciende y queda con pantalla negra','Ingresa notebook con pantalla negra.\r\nPresentaba problema de initranfs. Se corrigió con el comando correspondiente.','Solucionado','2026-04-30 10:17:58'),(5,9,'0005_2026','Ingresa Notebook para reparación. El mismo figuraba con poco espacio en disco y no dejaba guardar ningún documento','El equipo tenía instalado Sist Op. Wind 10 sin espacio en disco. Se hizo backup de toda información, se formateo y se instaló nuevo sistema operativo (Ubuntu 22) quedando con más espacio en disco y todas sus aplicaciones actualizadas. \r\nSe hicieron pruebas rigurosas para verificar su óptimo funcionamiento.','Solucionado','2026-04-30 10:21:00'),(6,11,'0006_2026','Uno de los parlantes no tenia ficha plug y el otro no emite sonido.','Se revisaron ambos no tenemos ficha de repuesto y el otro no enciende directamente.','Requiere Repuestos','2026-05-04 08:35:36'),(7,18,'0007_2026','Nesecita mantenimiento','Se realizo limpieza y mantenimiento del equipo, se cambio pasta térmica y se lubrico el cooler de la fuente.','Solucionado','2026-05-18 09:43:10'),(8,19,'0008_2026','Comprobar funcionamiento de las impresoras y realizar mantenimiento.','Se corroboro el funcionamiento de las misma, se realizo limpieza y cambio de toner, ambos equipos quedaron en funcionamiento.','Solucionado','2026-05-19 07:08:54'),(9,21,'0009_2026','El equipo no ingresaba a internet, zoom, correo. Había que configurar fecha y hora, chequear cargador por que no funcionaba. Sacar MAC wifi.','Se configuró fecha/hora, se hicieron pruebas de navegación (Internet, correos, App de Video llamadas), se obtuvo la MAC de wifi y se chequeo el cargador, el cual no funciona (Se deberá cambiar por uno nuevo)','Requiere Repuestos','2026-05-26 08:00:07'),(10,24,'0010_2026','Ingresa notebook informándonos que ha dejado de funcionar, por lo que no permite ingresar a ningún tipo de programa.','* El mísmo se chequeó completamente y se actualizó paquetes del sistema.\r\n* Se hicieron pruebas rigurosas y se verificó que funcionara perfectamente.','Solucionado','2026-06-05 11:21:19'),(11,26,'0011_2026','Sistema desactualizado, requiere limpieza y mantenimiento.','Se realizo limpieza de todo el equipo, cambio de pasta térmica y se actualizo el sistema operativo y sus aplicaciones.\r\nSe realizaron pruebas resultando en un optimo funcionamiento.','Solucionado','2026-06-10 11:03:58'),(12,29,'0012_2026','Hace mucho ruido al imprimir.','Se realizo limpieza completa del equipo, se realizaron pruebas con un toner nuevo resultando que el problema es el toner, se requiere reemplazar el mismo para que el equipo funcione correctamente.','Solucionado','2026-06-30 09:56:50'),(13,32,'0013_2026','El equipo aun contaba con el sistema operativo de fabrica, lo que hace que no tenga espacio para funcionar correctamente.','Se realiza resguardo de la información que tenia el equipo, se instalo una tarjeta micro sd de 64 gb donde se volcó la información que tenia el equipo y se realizo la migración de sistema operativo dejándolo completamente actualizado. \r\nSe realizaron pruebas resultando en un funcionamiento optimo.','Solucionado','2026-07-07 08:34:31'),(14,33,'0014_2026','Inicio bloqueado. \"Initfram\"','Se desbloqueo el inicio del equipo, y se reemplazo el cargador, ya que, el que trajo no funcionaba.','Solucionado','2026-07-07 11:39:32');
/*!40000 ALTER TABLE `pedidos_informes` ENABLE KEYS */;
UNLOCK TABLES;

