  `visible` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id_comentario`),
  KEY `idx_comentario_tarea` (`id_tarea`),
  KEY `idx_comentario_usuario` (`id_usuario`),
