INSERT INTO `tareas_comentarios` VALUES (1,24,13,'Se hablo con Hernan el dia 01 Junio por este tema indicando la importancia de contar con el UPS en el rack.','2026-06-02 04:40:12',1),(2,18,13,'Ya los tengo hechos pero me falta pasarlos en limpio.','2026-06-02 04:41:53',1),(3,26,13,'El celular de Erbin esta en el corportaivo','2026-06-03 05:09:08',1),(4,3,13,'Le dije a Rafa que queria la copia aunque este obsoleta','2026-06-08 05:14:56',0),(5,26,13,'La PC de Los Menucos la acercarn a la direccion el dia Miercoles 10 de Junio de 2026','2026-06-09 05:17:07',1),(6,21,11,'En la carpeta compartida en /INFORMATICA/Test Veloc. Internet 06-26, están las imágenes de los test, también hay un archivo \"Test de Velocidad Sedes  09-06-26.ods\" con la informacion de los relevamientos.','2026-06-09 09:26:20',1),(7,12,13,'Insistir a Orlando por esta tarea.','2026-06-30 07:53:09',1),(8,30,11,'Orlando dijo, que se van a quedar ahí provisionalmente, se van a acomodar los cables con precinto y cinta momentáneamente.','2026-06-30 10:23:03',1),(9,32,11,'Se realizo la instalación del puerto de red en el área de MPE.','2026-07-01 11:25:06',1);
