/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tareas_internas` (
  `id_tarea` int NOT NULL AUTO_INCREMENT,
  `titulo` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `estado` enum('Pendiente','En Proceso','Completada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pendiente',
  `comentario` text COLLATE utf8mb4_unicode_ci,
  `adjunto_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creado_por` int NOT NULL,
  `asignado_a` int DEFAULT NULL,
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_finalizacion` datetime DEFAULT NULL,
  `fecha_actualizacion` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `es_colaborativa` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id_tarea`),
  KEY `idx_estado` (`estado`),
  KEY `idx_asignado` (`asignado_a`),
  KEY `idx_creador` (`creado_por`),
  CONSTRAINT `fk_tarea_asignado` FOREIGN KEY (`asignado_a`) REFERENCES `usuarios` (`id_usuario`),
  CONSTRAINT `fk_tarea_creador` FOREIGN KEY (`creado_por`) REFERENCES `usuarios` (`id_usuario`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
