INSERT INTO `tareas_internas` VALUES (1,'Puesto de Casa de Abrigo','Agregar un puesto de red en la oficina de los de administración en Casa de Abrigo en la calle guido.','Completada',NULL,NULL,13,12,'2026-04-27 09:43:28','2026-05-04 08:46:56','2026-05-04 08:46:56',0),(2,'Jack RJ 45 - Caina Varones','Cambiar la ficha del cable al TV en Caina Varones que quedo la ficha y debe de quedar con el jack,','Completada',NULL,NULL,13,12,'2026-04-27 09:44:32','2026-04-28 08:46:13','2026-04-28 08:46:13',0),(3,'Backup RUN JAVA','Solicitar por enesima vez a Rafael la copia aunque este obsoleta','En Proceso',NULL,NULL,13,13,'2026-04-27 09:50:04',NULL,NULL,0),(5,'Preparar PC de linea 102','Es necesario realizar la configuracion de los siguientes usuarios:\r\n\r\nnatalia_gz7@hotmail.com \r\nUsuario: Nzanardi\r\nContraseña: Nz 110725\r\n\r\n\r\naabhugo@gmail.com\r\nUsuario: Haab\r\nContraseña: 1478520aa\r\n\r\n\r\nmaduriviviana@gmail.com\r\nUsuario:Vmaduri\r\nContraseña: Vm080425\r\n\r\n\r\ngeorgi.fimpel@gmail.com\r\nUsuario: cfimpel \r\nContraseña: Gf050325\r\n\r\n\r\nracheljmcj@hotmail.com\r\npinchulefraquel@gmail.com\r\nUsuario: Rpinchulef\r\nContraseña: Rp110522\r\n\r\nCompletar equipo con monitor, teclado y mouse. Realizarle una limpieza completa del gabinete.','Completada',NULL,NULL,13,11,'2026-04-28 07:22:57','2026-04-29 07:31:38','2026-04-29 07:31:38',0),(6,'Alinen Correo Electronico','Indicarle a Ailen que, aunque se le aumentó la cuota de disco del correo electrónico, o tiene que borrar los correos más antiguos o tiene que descargarlos de vez en cuando en Thunderbird, ya que la cuota es de 1000 MB, pero en un tiempo se le va a llenar nuevamente.','Completada',NULL,NULL,13,15,'2026-04-30 04:44:45','2026-05-04 08:52:27','2026-05-04 08:52:27',0),(7,'Presupuesto','Solicitar el presupuesto de las unidades de imagen de las impresoras Lexmarks MS421dn y B2546dw. \r\n\r\nFalta presupuesto de Shownet y uno de ML.','Completada','',NULL,13,12,'2026-05-04 05:02:33','2026-06-18 10:42:29','2026-06-18 10:42:29',0),(8,'Clonar - Formatear PC Globito Azul','Aproximadamente el 20 de Mayo Matias Colombil va a traer la PC del globito azul, se va a agregar un ssd y se va a instalar nuevamente. Es necesario realizar el backup del equipo y luego instalar el sistema del fichero biometrico.','Completada','El equipo nunca fue acercado por el personal del Globito Azul',NULL,13,13,'2026-05-04 08:55:53','2026-05-21 05:27:16','2026-05-21 05:27:16',0),(9,'Enviar Camara IP a Sierra Grande','Consultar por quien va a Sierra Grande para poder enviar la Camara para instalar en el Caina','Completada','La retiro Mariana para la instalación.',NULL,13,11,'2026-05-05 05:06:45','2026-05-12 06:38:41','2026-05-12 06:38:41',0),(10,'Seguimiento Solicitudes Orlando','Es necesario hacer un seguimiento con Orlando de los materiales que se le solicito para comprar. Para ver si avanzo en algo.','Completada','Se hablo con Orlando e informa que cuando tenga fondos va a adquirir los materiales mas pequeños.',NULL,13,13,'2026-05-12 04:39:59','2026-05-12 06:45:59','2026-05-12 06:45:59',0),(11,'Llevar PC Galpon Amarillo','Es necesario ir al Galpon Amarillo a instalar la PC y configurar la impresora y el escaner.','Completada','Diego la llevo y la dejo instalada.',NULL,13,11,'2026-05-12 04:45:44','2026-05-13 07:30:53','2026-05-13 07:30:53',0),(12,'Hablar con Orlando por Compra Materiales','Para ver si avanzo en algo.\r\n\r\nSe cierra solo cuando se compren los materiales.','En Proceso',NULL,NULL,13,12,'2026-05-12 07:11:36',NULL,'2026-05-18 11:15:24',0),(13,'Consultar Raquel Aviles Por Axon','Consultar con Raquel para si ver si tuvo alguna novedad con las consultas del WiFi en la provincia.\r\n\r\n\r\nSe envio nota por GDE a Raquel y Susana para que intervengan, ya que no tenemos novedades.','Completada','Se envio nota a Susana Sanelli y Raquel Aviles para que revisen la situacion y si es necesario involucren al area de legales.','tarea_13_1779954610_6a17f3b294ded.pdf',13,13,'2026-05-12 08:20:33','2026-05-28 04:50:10','2026-05-28 04:50:10',0),(14,'Tomar MACs Notebooks Mexico y Caseros','Tomar las MACs de las siguientes Notebooks en Mexico y Caseros:\r\n\r\nSoledad Segovia\r\nMarisa Petro\r\nSilverstone A-0271','Completada','Las notebook solicitadas quedaron funcionando perfectamente.',NULL,13,12,'2026-05-14 06:28:28','2026-05-21 05:23:40','2026-05-21 05:23:40',0),(15,'Relevamiento Provincial','Realizar un nuevo relevamiento en la provincia, enviando el anterior a los delegados para poder comparar.\r\nAsimismo incorpotar las PCs nuevas que se enviaron en 2025/2026','En Proceso',NULL,NULL,13,13,'2026-05-14 06:31:04',NULL,NULL,0),(16,'Configurar SAFyC','Configurar SAFyC en Jacobacci .\r\n\r\nEl agente es Rodolfo Campos.\r\nEl contacto esta en el corportivo.\r\n\r\nSi te informa que no tiene permisos al ingresar hay que escribirle a Altec. Yo ya les escribi y me informan que no es necesario usar el ddclient','Completada','Quedo funcionando el safyc.',NULL,13,11,'2026-05-14 09:57:20','2026-05-18 09:41:56','2026-05-18 09:41:56',0),(17,'Acomodar Estanteria','Acomodar todos lo que se pueda en la nueva estantería en el deposito de informática.','Completada','Ya se ubico la nueva estantería.',NULL,13,11,'2026-05-14 11:13:08','2026-05-20 08:09:21','2026-05-20 08:09:21',0),(18,'Protocolos','hacer protocolos para casos especiales equipos informaticos:\r\nP1: Contenido no apto para menores.\r\nP2: Rotura por Mal Uso.\r\nEtc, etc','Completada','Se completo el protocolo de contenido inapropiado, el mismo esta en \r\n/\r\n└── compartidas/\r\n    └── INFORMATICA/\r\n        └── Protocolos Actuacion/\r\n            └── Protocolo Contenido Inapropiado.pdf',NULL,13,13,'2026-05-19 11:05:34','2026-06-18 04:51:29','2026-06-18 04:51:29',0),(20,'Script Carpetas Compartidas Systemd','Hacer el script de Carpetas Compartidas en systemd para mexico y caseros.\r\n\r\nLos archivos de systemd estan en .21 /home/Perfil/temporal\r\n\r\nHay que hacer una copia del CompartidaSystemD.sh que es el script de central. El unico cambio seria de donde copiar los archivos systemd (Crear una nueva carpeta en http://10.114.85.21/Senaf/Dominio/)','Completada','Se creo el script que esta alojado en 10.114.85.21 /home/Perfil/CompartidaSystemDMexico.sh',NULL,13,13,'2026-05-20 06:42:20','2026-05-21 05:24:23','2026-05-21 05:24:23',0),(21,'Relevamiento de Ancho de Banda de Internet','Comunicarse con referentes de cada sede y conectarse de forma remota para hacer captura de pantalla del speed test. Registrar de manera sistemática en una carpeta para poder identificar de que sede y que proveedor estamos relevando. Luego enviar los reclamos a los proveedores y a tarifados.','Completada','',NULL,15,11,'2026-05-21 05:16:12','2026-06-09 09:28:53','2026-06-09 09:28:53',0),(22,'Relevamiento de impresoras','Relevar y agregar al SITIA todas las impresoras que están en el deposito.','Completada','Ya estan cargadas en Sitia todas las impresoras disponibles para entregar, nuevas y usadas.',NULL,15,11,'2026-05-22 05:23:45','2026-05-28 05:09:10','2026-05-28 05:09:10',0),(23,'Puesto red Mesa de Entrada','En las semanas del 26/05 y 05/06 es necesario la instalacion de un nuevo puesto de red en la oficina de mesa de entrada.\r\n\r\nLa PC esta lista para entregar una vez que se instale el puesto.','Completada','Se completo la instalación de puesto de red. El mismo quedó funcionando de manera óptima.',NULL,13,12,'2026-05-26 09:24:14','2026-06-08 08:35:01','2026-06-08 08:35:01',0),(24,'Consultar Hernan / Luis UPS','Consultar con LUis y Hernan para poder instalar el UPS en Mexico y Caseros, recordando de como el mismo va afuera del RACK, deben de poner alguna barrera por seguridad','Completada','Se le informo a Luis la necesidad de que puedan generar algun cerco para el rack, ya que el UPS a instalar es muy grande y no cabe dentro del rack, por lo que debe de estar protegido.',NULL,13,13,'2026-05-26 10:55:44','2026-06-03 04:49:24','2026-06-03 04:49:24',0),(25,'WiFI Notebook Libertad Asistida','Ir a Mexico y Caseros a ver bien la MAC de la PC de libertad asistida. La mac que se informo ya se configuro en unifi y siguen sin poder conectarse al WiFi','Completada','Se aplicó correctamente la conexión a wifi al equipo.',NULL,13,12,'2026-06-02 04:41:23','2026-06-04 08:11:49','2026-06-04 08:11:49',0),(26,'Comunicarse con Los Menucos','Comunicarse con los Menucos por PC RRHH con Falla, ver si pueden indicar bien cual es la falla, tratar de ver cual es el problema. Si no se puede ver bien, que la envien por el camion que pasa la semana que viene.','Completada','Se hizo un service completo al equipo y quedó funcionando de manera óptima.',NULL,13,12,'2026-06-03 05:08:17','2026-06-18 10:47:14','2026-06-18 10:47:14',0),(27,'Migrar PC Escritorio','Migrar la PC Propia y dejar la anterior lista para entregar.\r\n\r\nPor el momento fuera de dominio.','Completada','Se completó la tarea con éxito.',NULL,13,12,'2026-06-09 05:15:31','2026-06-18 10:41:18','2026-06-18 10:41:18',0),(28,'Migrar PC Escritorio','Migrar la PC Propia y dejar la anterior lista para entregar.\r\n\r\nPor el momento fuera de dominio.','Completada','Ya esta migrada, y la PC anterior lista para entregar, esta en el deposito y cargada en el sistema.',NULL,13,11,'2026-06-09 05:16:14','2026-06-16 05:09:23','2026-06-16 05:09:23',0),(29,'Acomodar Camara Deposito','Acomodar la camara del deposito de central, La camara es la que esta afuera sobre el porton del mismo.\r\nSolicitar escalera a Logistica/Mantenimiento.','Completada','La cámara se encuentra nuevamente en su posición de configuración inicial.',NULL,13,12,'2026-06-29 07:48:38','2026-06-29 09:48:16','2026-06-29 09:48:16',1),(30,'Corrección Cableado','Hablar con Orlando por si Mra y la otra chica se van a quedar en el mismo lugar. Si se quedan en el mismo lugar dejar el cableado correcto porque esta de forma temporal','Completada','',NULL,13,11,'2026-06-30 07:49:40','2026-07-01 13:46:37','2026-07-01 13:46:37',1),(31,'Verificar Norberto','Verificar si Norberto se va a Valle Inferior, en ese caso averiguar si se va con su PC','Completada','Se hizo service completo de equipo para trasladarlo a sede valle inferior.',NULL,13,12,'2026-06-30 07:50:29','2026-07-01 08:45:50','2026-07-01 08:45:50',1),(32,'Puesto de Red','Instalar un nuevo puesto de red en el area de MPE de central','Completada','',NULL,13,11,'2026-07-01 07:56:37','2026-07-01 11:25:21','2026-07-01 11:25:21',1),(33,'Poner un puesto de red en Ing. Jacobacci','Agregar un puesto de red en la sede SeNAF Ingeniero Jacobacci.','En Proceso',NULL,NULL,13,NULL,'2026-07-08 13:40:14',NULL,NULL,1);
