  `ultimo_acceso` datetime DEFAULT NULL,
  `modificado_por` int DEFAULT NULL COMMENT 'ID del usuario que realizó la última modificación',
  `fecha_modificacion` datetime DEFAULT NULL,
  PRIMARY KEY (`id_usuario`),
